export const QUIZ_CATEGORIES = [
  "Sanskrit foundations and terminology",
  "Pāṇinian grammar and Aṣṭādhyāyī concepts",
  "Sandhi",
  "Samāsa",
  "Sup, tiṅ, vibhakti, and kāraka",
  "Dhātu, lakāra, and verb formation",
  "Pratyaya and word formation",
  "Computational linguistics, NLP, and explainability",
  "Sanskrit learning methods and application",
] as const;

export type QuizCategory = (typeof QUIZ_CATEGORIES)[number];
export type QuizDifficulty = "Beginner" | "Intermediate" | "Advanced";

export interface QuizQuestion {
  id: string;
  category: QuizCategory;
  difficulty: QuizDifficulty;
  question: string;
  questionSanskrit?: string;
  options: string[];
  correctAnswer: string;
  correctAnswerIndex: number;
  hint: string;
  explanation: string;
  optionExplanations: string[];
  sourceNote: string;
  sutraCitation: string;
  citationNumbers: number[];
}

type QuestionSeed = {
  question: string;
  answer: string;
  distractors: [string, string, string];
  explanation: string;
  hint?: string;
  difficulty: QuizDifficulty;
  sourceNote: string;
  sutraCitation?: string;
};

function createQuestionHint(question: string, category: QuizCategory): string {
  const stopWords = new Set([
    "a", "an", "and", "are", "as", "at", "be", "broadly", "does", "for", "from", "how", "in",
    "is", "it", "of", "on", "or", "the", "to", "what", "which", "why", "with", "mean", "example",
    "curated", "provided", "following", "broad", "many",
  ]);
  const focus = (question.match(/[\p{L}\p{N}][\p{L}\p{N}'’āīūṛṝḷṃḥṁṅñṭḍṇśṣ\-]*/giu) ?? [])
    .filter((word) => !stopWords.has(word.toLowerCase()))
    .slice(0, 4)
    .join(" ");
  const personalize = (clue: string) =>
    focus ? `${clue} Apply that distinction to the prompt's focus on “${focus}.”` : clue;
  const hintRules: [RegExp, string][] = [
    [/dhātu|verbal root/i, "Separate the underlying verbal base from the endings and operations added to build a form."],
    [/prātipadika|nominal base/i, "Think about the base that is ready to take nominal inflection, rather than a finished sentence form."],
    [/pratyāhāra|initial sound|final marker/i, "Recall how a compact sound-group label uses a start point and a marker in the Śiva Sūtras."],
    [/it marker|it-marker|anubandha/i, "Distinguish a technical marker's grammatical function from whether it remains in the final spoken form."],
    [/anuvṛtti/i, "Consider how a term or condition stated earlier can remain understood in later rules."],
    [/adhikāra/i, "Look for the rule-system device that establishes scope over a following sequence."],
    [/governing scope|scope note/i, "Look for the rule-system device that establishes scope over a following sequence."],
    [/vipratiṣedha|rule conflict|conflicting rules/i, "First check whether both rules apply in the same context; then consider the stated priority principle."],
    [/saṁjñā|saṃjñā|technical designation/i, "Think of the role of a technical label: it lets later rules refer compactly to a defined class."],
    [/closest substitute|place and manner of articulation|sthāne/i, "Compare the articulation of the sounds involved; the rule's criterion is phonetic closeness in the relevant environment."],
    [/sandhi|guṇa|vṛddhi|yaṇ|vowel|visarga|sound change/i, "Focus on the neighboring sounds and the phonological environment, not on word meaning alone."],
    [/samāsa|compound|vigraha|dvandva|bahuvrīhi|tatpuruṣa|avyayībhāva/i, "Ask how the members relate to one another and whether the question is about structure, meaning, or a cautious analysis."],
    [/vibhakti|kāraka|case|nominal ending|sup\b/i, "Keep the overt nominal form distinct from the semantic role it may express in context."],
    [/tiṅ|lakāra|tense|person|finite verb|verb ending|conjugation/i, "Trace the verbal base, the requested tense-or-mood distinction, and the person/number ending separately."],
    [/kṛt|taddhita|strī-pratyaya|affix|derivation|word formation/i, "Distinguish an affix that derives a new stem from endings that inflect an existing base."],
    [/tokeniz|part-of-speech|tagging|morpholog|syntactic|parsing/i, "Identify which processing layer is being asked about; segmentation, labels, word structure, and sentence structure are different tasks."],
    [/explainab|provenance|benchmark|evaluation|pattern-matching demo|NLP pipeline|parser/i, "Choose the claim that makes system evidence and limits inspectable; transparency does not itself prove correctness."],
    [/learning|lesson|formative feedback|spaced revision|cognitive load/i, "Focus on the learning process being described and avoid treating a design principle as proof of measured outcomes."],
    [/how many adhyāyas|how many pādas|sūtra number|reference address|chapter and pāda|locate.*rule/i, "Treat a numbered reference as an address in the text, then distinguish locating a rule from interpreting its operation."],
    [/which sūtra.*(?:gives|defines|designation|cited)|which rule.*cited/i, "Look for the rule that defines the requested term or operation; distinguish it from nearby rule references."],
  ];
  const matched = hintRules.find(([pattern]) => pattern.test(question));
  if (matched) return personalize(matched[1]);

  const categoryHints: Record<QuizCategory, string> = {
    "Sanskrit foundations and terminology": "Identify the grammatical level or technical term being defined, and distinguish it from neighboring concepts.",
    "Pāṇinian grammar and Aṣṭādhyāyī concepts": "Use the rule's role in the grammatical system; distinguish a convention, a technical label, and an operation.",
    Sandhi: "Inspect the sounds at the boundary and the conditions under which a phonological change is described.",
    Samāsa: "Consider the relationship between the members and the compound's function in its sentence context.",
    "Sup, tiṅ, vibhakti, and kāraka": "Separate nominal inflection, grammatical case, and the participant's semantic role.",
    "Dhātu, lakāra, and verb formation": "Work from the verbal base and distinguish the requested tense/mood, class, and ending information.",
    "Pratyaya and word formation": "Distinguish derivational steps from inflection and track what kind of base an affix attaches to.",
    "Computational linguistics, NLP, and explainability": "Identify the computational task and what its output can—and cannot—establish.",
    "Sanskrit learning methods and application": "Reason from the stated learning goal and evidence; do not infer effectiveness without evaluation.",
  };
  return personalize(categoryHints[category]);
}

const grammarNote =
  "Source note: Primary text reference and short gloss are included as a teaching aid; the site's English explanations are editorial and should be checked against a named scholarly edition before formal citation. See References [1].";
const nlpNote =
  "Source note: General computational-linguistics context; this question does not assert that this website implements or evaluates a complete parser. See References [2].";
const learningNote =
  "Source note: General learning-design concept. The cited cognitive-load work does not evaluate this website or establish its effectiveness. See References [3].";

function buildCategory(
  category: QuizCategory,
  prefix: string,
  questions: QuestionSeed[],
): QuizQuestion[] {
  return questions.map((seed, index) => {
    const options = [seed.answer, ...seed.distractors];
    return {
      id: `${prefix}-${String(index + 1).padStart(2, "0")}`,
      category,
      difficulty: seed.difficulty,
      question: seed.question,
      options,
      correctAnswer: seed.answer,
      correctAnswerIndex: 0,
      hint: seed.hint ?? createQuestionHint(seed.question, category),
      explanation: seed.explanation,
      optionExplanations: options.map((option) =>
        option === seed.answer
          ? seed.explanation
          : `The choice “${option}” does not best answer what the prompt asks. ${seed.explanation}`,
      ),
      sourceNote: seed.sourceNote,
      sutraCitation: seed.sutraCitation ?? "No specific sūtra citation; consult the source note.",
      citationNumbers: [...seed.sourceNote.matchAll(/References \[(\d+)\]/g)].map((match) => Number(match[1])),
    };
  });
}

