export const ADDITIONAL_QUIZ_QUESTION_COUNT = Object.values(additionalQuestionsByCategory)
  .reduce((total, questions) => total + questions.length, 0);

export const QUIZ_QUESTION_COUNTS = QUIZ_CATEGORIES.reduce(
  (counts, category) => ({
    ...counts,
    [category]: VERIFIED_QUIZ_QUESTIONS.filter((question) => question.category === category).length,
  }),
  {} as Record<QuizCategory, number>,
);

export const QUIZ_CONTENT_AUDIT = {
  total: VERIFIED_QUIZ_QUESTIONS.length,
  completeHints: VERIFIED_QUIZ_QUESTIONS.filter((question) => question.hint.trim().length > 0).length,
  completeExplanations: VERIFIED_QUIZ_QUESTIONS.filter((question) => question.explanation.trim().length > 0).length,
  completeOptionExplanations: VERIFIED_QUIZ_QUESTIONS.filter(
    (question) =>
      question.optionExplanations.length === question.options.length &&
      question.optionExplanations.every((explanation) => explanation.trim().length > 0),
  ).length,
  incompleteQuestionIds: VERIFIED_QUIZ_QUESTIONS
    .filter((question) =>
      !question.hint.trim() ||
      !question.explanation.trim() ||
      question.optionExplanations.length !== question.options.length ||
      question.optionExplanations.some((explanation) => !explanation.trim()),
    )
    .map((question) => question.id),
};
